let connection;
export function openHistory(){if(connection)return connection;connection=new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('此浏览器不支持本地记录保存。'));return}const r=indexedDB.open('dongjian-history',1);r.onupgradeneeded=()=>{const db=r.result;db.createObjectStore('records',{keyPath:'id'});db.createObjectStore('settings')};r.onerror=()=>reject(Error('无法打开本地记录，请检查浏览器存储权限。'));r.onblocked=()=>reject(Error('存储被其他标签页占用，请关闭旧标签页后重试。'));r.onsuccess=()=>resolve(r.result)});return connection}
export async function allRecords(){const db=await openHistory();return new Promise((resolve,reject)=>{const req=db.transaction('records').objectStore('records').getAll();req.onsuccess=()=>resolve(req.result.sort((a,b)=>b.savedAt.localeCompare(a.savedAt)));req.onerror=()=>reject(Error('读取历史记录失败。'))})}
export async function saveRecord(record){const db=await openHistory();return new Promise((resolve,reject)=>{const tx=db.transaction(['records','settings'],'readwrite');tx.objectStore('records').put(record);tx.objectStore('settings').put(record.id,'lastRecord');tx.oncomplete=()=>resolve(record);tx.onabort=tx.onerror=()=>reject(Error('记录未保存：浏览器存储不可用或空间不足。请导出当前报告后重试。'))})}
export async function lastRecord(){const db=await openHistory();return new Promise((resolve,reject)=>{const tx=db.transaction(['records','settings']);const setting=tx.objectStore('settings').get('lastRecord');setting.onsuccess=()=>{if(!setting.result){resolve(null);return}const r=tx.objectStore('records').get(setting.result);r.onsuccess=()=>resolve(r.result||null);r.onerror=reject};setting.onerror=reject})}
export async function importRecords(records){const db=await openHistory();const existing=await allRecords();const ids=new Set(existing.map(r=>r.id));const next=records.filter(r=>{if(ids.has(r.id))return false;ids.add(r.id);return true});return new Promise((resolve,reject)=>{const tx=db.transaction('records','readwrite');for(const r of next)tx.objectStore('records').put(r);tx.oncomplete=()=>resolve(next.length);tx.onabort=tx.onerror=()=>reject(Error('备份导入失败，未完成写入。'))})}
